#requires -version 5.1
$ErrorActionPreference='Stop'
$projectRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));Set-Location -LiteralPath $projectRoot
. (Join-Path $projectRoot 'MemoryClear.ps1') -SmokeTest -ControlsOnly
Import-Module (Join-Path $projectRoot 'app\MemoryClear.Tasks.psm1')
$results=New-Object 'System.Collections.Generic.List[object]'
function Assert {param([bool]$Value,[string]$Message);if(-not$Value){throw $Message}}
function Check {param([string]$Name,[scriptblock]$Action);try{&$Action;$results.Add([pscustomobject]@{Name=$Name;Passed=$true;Error=''})}catch{$results.Add([pscustomobject]@{Name=$Name;Passed=$false;Error=$_.Exception.Message})}}
function Click {param($Button);$Button.RaiseEvent([Windows.RoutedEventArgs]::new([Windows.Controls.Primitives.ButtonBase]::ClickEvent))}
function Identity { [pscustomobject]@{Pid=123;StartTicks=123456;Path='C:\Apps\optin.exe';Sid='fixture-user';Session=1;Critical=$false;Known=$true} }
$context=[pscustomobject]@{UserSid='fixture-user';SessionId=1;SelfId=900;WindowsRoot='C:\Windows\';Services=@{};ServicesKnown=$true};$settings=[pscustomobject]@{SchemaVersion=1;ProtectedPaths=@();AllowClosePaths=@('C:\Apps\optin.exe');RefreshSeconds=3;AutoKill=$false}
Check 'Three visible level controls, Normal default and hidden legacy selector' {Assert ($ui.MemoryLevel1.IsChecked-and$ui.MemoryLevel2-and$ui.MemoryLevel3-and$ui.StrongClear.Visibility-eq'Collapsed'-and-not$ui.StrongClear.IsChecked) 'Wrong Memory selector'}
Check 'Level2 preserves Strong trim and explains reload cost' {$ui.MemoryLevel2.IsChecked=$true;Click $ui.MemoryLevel2;Assert ($ui.StrongClear.IsChecked-and$ui.ClearMemory.Content-eq'Clear'-and$ui.MemoryEffects.Text.Contains('nạp lại')) 'Strong mapping changed'}
Check 'Level3 explicitly previews opt-in effects; no executor shortcut' {$ui.MemoryLevel3.IsChecked=$true;Click $ui.MemoryLevel3;Assert (-not$ui.StrongClear.IsChecked-and$ui.ClearMemory.Content-eq'Xem tác vụ mức 3'-and$ui.MemoryEffects.Text.Contains('Chỉ preview')) 'Preview gate misleading';$p=Get-MCTaskPolicy;Assert (-not$p.executionEnabled-and-not$p.forceEnabled-and-not$p.autoForceAfterTimeout) 'Unsafe executor flag'}
Check 'Shared operation lock disables every level and Temp entry' {Set-MCOperationState $true;Assert (-not$ui.MemoryLevel1.IsEnabled-and-not$ui.MemoryLevel2.IsEnabled-and-not$ui.MemoryLevel3.IsEnabled-and-not$diskUI.DiskClean.IsEnabled) 'Level race enabled';Set-MCOperationState $false;$ui.MemoryLevel1.IsChecked=$true;Click $ui.MemoryLevel1}
Check 'Opt-in exact executable only; no names or RAM CPU inference' {$c=Test-MCTaskCandidate (Identity) $context $settings;Assert ($c.Eligible-and$c.Action-eq'GracefulOnly'-and-not$c.ForceAllowed) 'Opt-in missing';$s=$settings.PSObject.Copy();$s.AllowClosePaths=@();Assert (-not(Test-MCTaskCandidate (Identity) $context $s).Eligible) 'Default selected task';$s.AllowClosePaths=@('C:\Apps\optin.exe.bak');Assert (-not(Test-MCTaskCandidate (Identity) $context $s).Eligible) 'Sibling path matched'}
Check 'Opt-in cannot override critical, unknown, self, service or unavailable inventory' {$id=Identity;$id.Critical=$true;Assert (-not(Test-MCTaskCandidate $id $context $settings).Eligible) 'Critical bypass';$id=Identity;$id.Known=$false;Assert (-not(Test-MCTaskCandidate $id $context $settings).Eligible) 'Unknown bypass';$id=Identity;$id.Pid=900;Assert (-not(Test-MCTaskCandidate $id $context $settings).Eligible) 'Self bypass';$c=$context.PSObject.Copy();$c.Services=@{123=$true};Assert (-not(Test-MCTaskCandidate (Identity) $c $settings).Eligible) 'Service bypass';$c.ServicesKnown=$false;Assert (-not(Test-MCTaskCandidate (Identity) $c $settings).Eligible) 'Missing inventory bypass'}
Check 'Different SID/session, Windows path and user protected path remain blocked' {$id=Identity;$id.Sid='other';Assert (-not(Test-MCTaskCandidate $id $context $settings).Eligible) 'SID bypass';$id=Identity;$id.Session=2;Assert (-not(Test-MCTaskCandidate $id $context $settings).Eligible) 'Session bypass';$id=Identity;$id.Path='C:\Windows\System32\x.exe';Assert (-not(Test-MCTaskCandidate $id $context $settings).Eligible) 'Windows bypass';$s=$settings.PSObject.Copy();$s.ProtectedPaths=@('C:\Apps\optin.exe');Assert (-not(Test-MCTaskCandidate (Identity) $context $s).Eligible) 'Protection bypass'}
Check 'Foreground PID, same executable and unknown foreground keep tasks' {Assert (-not(Test-MCTaskCandidate (Identity) $context $settings @([int]123)).Eligible) 'Foreground PID bypass';Assert (-not(Test-MCTaskCandidate (Identity) $context $settings @() @('C:\Apps\optin.exe')).Eligible) 'Same executable bypass';Assert (-not(Test-MCTaskCandidate (Identity) $context $settings @() @() $false).Eligible) 'Unknown foreground bypass'}
Check 'Native current-host preview has no process action capability' {$identity=[MemoryClear.Native]::Inspect($PID);$row=[pscustomobject]@{Pid=$PID;StartTicks=$identity.StartTicks;Name='Own PowerShell';Path=$identity.Path;RamMB=0};$r=New-MCTaskPreview @($row);Assert (-not$r.ExecutionEnabled-and$r.ExpiresUtc-gt$r.CreatedUtc-and$r.EligibleCount-eq0) 'Preview granted authority';Assert ([MemoryClear.Native]::Inspect($PID).StartTicks-eq$identity.StartTicks) 'Own process changed'}
Check 'Task window loads readonly grid and disabled execute action' {$reader=New-Object Xml.XmlNodeReader ([xml](Get-Content app\MemoryTaskView.xaml -Raw -Encoding UTF8));$d=[Windows.Markup.XamlReader]::Load($reader);try{Assert ($d.FindName('TaskItems').IsReadOnly-and-not$d.FindName('TaskExecute').IsEnabled) 'Execute opened'}finally{$d.Close()}}
Check 'Offscreen three-level main view renders' {$content=$window.Content;$content.Measure([Windows.Size]::new(1120,780));$content.Arrange([Windows.Rect]::new(0,0,1120,780));$content.UpdateLayout();$bmp=[Windows.Media.Imaging.RenderTargetBitmap]::new(1120,780,96,96,[Windows.Media.PixelFormats]::Pbgra32);$bmp.Render($content);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($bmp));$f=[IO.File]::Create((Join-Path $projectRoot 'artifacts\memory-levels-preview.png'));try{$encoder.Save($f)}finally{$f.Dispose()}}
$window.Close()
$r=[pscustomobject]@{Timestamp=[DateTime]::UtcNow.ToString('o');Runtime=$PSVersionTable.PSVersion.ToString();Passed=@($results|Where-Object{$_.Passed}).Count;Failed=@($results|Where-Object{-not$_.Passed}).Count;Checks=$results.ToArray();Scope='Memory3 policy pure fixtures/readonly current-host preview/level bindings/offscreen WPF; no close/force/trim execution';TaskExecutionEnabled=$false;Image='artifacts/memory-levels-preview.png';Unverified=@('Live nonempty opt-in native exe fingerprint branch','Task modal worker/DispatcherTimer human interaction','Level3 close/save prompt/timeout/native races and safety gates','Win10/DPI acceptance')}
$r|ConvertTo-Json -Depth 7|Set-Content (Join-Path $projectRoot 'docs\verification\memory-level-tests.json') -Encoding UTF8
Write-Host ('Memory levels: '+$r.Passed+' passed, '+$r.Failed+' failed');if($r.Failed){$r.Checks|Where-Object{-not$_.Passed}|Format-List;exit 1}
